    function run(uint amount, uint64 unlockTime, uint collectAmount, uint64 delta) public payable {
        require(amount <= address(this).balance);
        require(amount > 0);

        c.Put{value: amount}(unlockTime);
        (uint accUnlock0, uint accBalance0) = c.Acc(address(this));

        uint expectedUnlock0 = unlockTime > block.timestamp ? uint(unlockTime) : block.timestamp;
        assert(accBalance0 == amount && accUnlock0 == expectedUnlock0);

        require(amount <= address(this).balance);
        c.Put{value: amount}(unlockTime);
        (uint accUnlock1, uint accBalance1) = c.Acc(address(this));

        uint expectedUnlock1 = unlockTime > block.timestamp ? uint(unlockTime) : block.timestamp;
        assert(accBalance1 == amount + amount && accUnlock1 == expectedUnlock1);

        uint64 later = uint64(block.timestamp) + delta;
        require(later >= block.timestamp);
        uint valueFallback = 10;
        require(valueFallback <= address(this).balance);
        (bool sF, ) = address(c).call{value: valueFallback}("");
        sF;
        (uint accUnlock2, uint accBalance2) = c.Acc(address(this));
        assert(accBalance2 == amount + amount + valueFallback && accUnlock2 >= uint(later));

        uint balanceBefore = accBalance2;
        uint cEthBefore = address(c).balance;
        c.Collect(collectAmount);
        (uint accUnlock3, uint accBalance3) = c.Acc(address(this));

        uint64 unlockBefore = uint64(accUnlock2);
        if (accUnlock2 <= block.timestamp) {
            assert(accBalance3 == balanceBefore);
        } else {
            assert(accBalance3 == balanceBefore);
            assert(address(c).balance == cEthBefore);
        }
    }

    receive() external payable {}
