contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint _unlockTime, uint _am) public payable {
        require(address(this).balance >= 1 ether + _am, "insufficient balance");
        c.Put{value: 1 ether}(_unlockTime);
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        require(beforeBalance >= c.MinSum() && beforeBalance >= _am);

        bool reverted;
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

        assert(
            reverted ||
            (afterBalance == beforeBalance - _am && address(c).balance == (1 ether - _am))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint _unlockTime, uint _am) public payable {
        require(_am > 0);
        require(address(this).balance >= _am);

        (, uint beforeBal) = c.Acc(address(this));

        c.Put{value: _am}(_unlockTime);

        (uint afterPutUnlock, uint afterPutBal) = c.Acc(address(this));
        require(afterPutBal == beforeBal + _am);

        uint cBalBeforeCollect = address(c).balance;

        bool reverted;
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterCollectUnlock, uint afterCollectBal) = c.Acc(address(this));

        assert(
            reverted ||
            (afterCollectBal == afterPutBal - _am && address(c).balance == cBalBeforeCollect - _am)
        );
    }

    receive() external payable {}
}
